import { HostValidationError } from "./errors.mjs";

const INVALID_HOST_CHARACTERS = /[!@#$%^&'"*()+=:;/]/;

function isBracketedIpv6Host(host) {
  return host.startsWith("[") && host.endsWith("]");
}

function hasOnlyPeriods(host) {
  return host.length > 0 && /^[.]+$/.test(host);
}

export function normalizeHost(host) {
  const text = String(host);

  if (text === "") {
    return "";
  }

  if (isBracketedIpv6Host(text)) {
    return text.toLowerCase();
  }

  if (hasOnlyPeriods(text) || text.includes("..") || INVALID_HOST_CHARACTERS.test(text)) {
    throw new HostValidationError(text);
  }

  return text.toLowerCase();
}

