import { normalizeHost } from "./host.mjs";
import { parseUrlish } from "./parse.mjs";
import { serializeUrlish } from "./serialize.mjs";

export function setHostOnUrl(rawUrl, rawHost) {
  const model = parseUrlish(rawUrl);
  model.host = normalizeHost(rawHost);
  model.hasAuthority = true;
  return serializeUrlish(model);
}

