    }
    authority += "@";
  }

  authority += model.host ?? "";

  if (model.port !== undefined) {
    authority += `:${model.port}`;
  }

  return authority;
}

function serializePathWithAuthority(path, authority) {
  if (path === "") {
    return "";
  }

  if (authority !== "" && !path.startsWith("/")) {
    return `/${path}`;
  }

  return path;
