import { formatHelp, formatParseError, getProgramName } from "./lib/cli/messages.mjs";
import { CliParseError, parseCommandLine } from "./lib/cli/parseArgs.mjs";
import { HostValidationError } from "./lib/url/errors.mjs";
import { setHostOnUrl } from "./lib/url/furlish.mjs";

function main() {
  const programName = getProgramName(process.argv[1]);

  let parsedArgs;
  try {
    parsedArgs = parseCommandLine(process.argv.slice(2));
  } catch (error) {
    if (error instanceof CliParseError) {
      process.stderr.write(formatParseError(programName, error.message));
      process.exitCode = 2;
      return;
    }
    throw error;
  }

  if (parsedArgs.help) {
    process.stdout.write(formatHelp(programName));
    return;
  }

  try {
    const output = setHostOnUrl(parsedArgs.values.a, parsedArgs.values.b);
    process.stdout.write(`${output}\n`);
  } catch (error) {
    if (error instanceof HostValidationError) {
      process.stderr.write(`ValueError: ${error.message}\n`);
      process.exitCode = 1;
      return;
    }
    throw error;
  }
}

main();

