function basename(filePath) {
  if (!filePath) {
    return "";
  }

  const parts = String(filePath).split(/[\\/]/);
  return parts[parts.length - 1] || "";
}

export function getProgramName(scriptPath) {
  return basename(scriptPath) || "node";
}

export function formatUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

export function formatHelp(programName) {
  return `${formatUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

export function formatParseError(programName, message) {
  return `${formatUsage(programName)}\n${programName}: error: ${message}\n`;
}
