import { HostValidationError } from "./errors.mjs";

const INVALID_HOST_CHARACTERS = /[!@#$%^&'"*()+=:;/]/;

function isBracketedIpv6Host(host) {
  return host.startsWith("[") && host.endsWith("]");
}

function hasOnlyPeriods(host) {
  return host.length > 0 && /^[.]+$/.test(host);
}

function containsNonAscii(host) {
  for (let index = 0; index < host.length; index += 1) {
    if (host.charCodeAt(index) > 0x7f) {
      return true;
    }
  }

  return false;
}

function punycodeHost(host) {
  try {
    return new URL(`http://${host}`).hostname;
  } catch {
    return host.toLowerCase();
  }
}

export function normalizeHost(host) {
  const text = String(host);

  if (text === "") {
    return "";
  }

  if (isBracketedIpv6Host(text)) {
    return text.toLowerCase();
  }

  if (text.startsWith(".") || hasOnlyPeriods(text) || text.includes("..") || INVALID_HOST_CHARACTERS.test(text)) {
    throw new HostValidationError(text);
  }

  if (containsNonAscii(text)) {
    return punycodeHost(text);
  }

  return text.toLowerCase();
}
