function splitFragment(text) {
  const index = text.indexOf("#");
  if (index === -1) {
    return {
      fragment: "",
      hasFragment: false,
      withoutFragment: text,
    };
  }

  return {
    fragment: text.slice(index + 1),
    hasFragment: true,
    withoutFragment: text.slice(0, index),
  };
}

function splitQuery(text) {
  const index = text.indexOf("?");
  if (index === -1) {
    return {
      hasQuery: false,
      query: "",
      withoutQuery: text,
    };
  }

  return {
    hasQuery: true,
    query: text.slice(index + 1),
    withoutQuery: text.slice(0, index),
  };
}

function parseAuthority(authority) {
  let username;
  let password;
  let host = "";
  let port;
  let hostPort = authority;

  const atIndex = authority.lastIndexOf("@");
  if (atIndex !== -1) {
    const userInfo = authority.slice(0, atIndex);
    hostPort = authority.slice(atIndex + 1);

    const colonIndex = userInfo.indexOf(":");
    if (colonIndex === -1) {
      username = userInfo;
    } else {
      username = userInfo.slice(0, colonIndex);
      password = userInfo.slice(colonIndex + 1);
    }
  }

  if (hostPort.startsWith("[")) {
    const closingBracketIndex = hostPort.indexOf("]");
    if (closingBracketIndex !== -1) {
      host = hostPort.slice(0, closingBracketIndex + 1).toLowerCase();
      const remainder = hostPort.slice(closingBracketIndex + 1);
      if (remainder.startsWith(":")) {
        port = remainder.slice(1);
      }
    } else {
      host = hostPort.toLowerCase();
    }
  } else {
    const lastColonIndex = hostPort.lastIndexOf(":");
    if (lastColonIndex !== -1 && hostPort.indexOf(":") === lastColonIndex) {
      host = hostPort.slice(0, lastColonIndex).toLowerCase();
      port = hostPort.slice(lastColonIndex + 1);
    } else {
      host = hostPort.toLowerCase();
    }
  }

  return {
    host,
    password,
    port,
    username,
  };
}

function normalizePath(path) {
  return path.replace(/ /g, "%20");
}

export function parseUrlish(rawUrl) {
  const originalText = String(rawUrl);
  const text = originalText.replace(/^\s+/, "");
  const hadLeadingWhitespace = text !== originalText;
  const schemeMatch = text.match(/^([A-Za-z][A-Za-z0-9+.-]*):(.*)$/s);
  const scheme = schemeMatch ? schemeMatch[1].toLowerCase() : "";
  const afterScheme = schemeMatch ? schemeMatch[2] : text;

  let hasAuthority = false;
  let authority = "";
  let afterAuthority = afterScheme;

  if (afterScheme.startsWith("//")) {
    hasAuthority = true;
    const authorityBody = afterScheme.slice(2);
    const authorityEnd = authorityBody.search(/[/?#]/);

    if (authorityEnd === -1) {
      authority = authorityBody;
      afterAuthority = "";
    } else {
      authority = authorityBody.slice(0, authorityEnd);
      afterAuthority = authorityBody.slice(authorityEnd);
    }
  }

  const fragmentParts = splitFragment(afterAuthority);
  const queryParts = splitQuery(fragmentParts.withoutFragment);
  const authorityParts = parseAuthority(authority);
  const path = normalizePath(queryParts.withoutQuery);

  if (hadLeadingWhitespace) {
    return {
      hasAuthority: false,
      hasFragment: fragmentParts.hasFragment,
      hasQuery: queryParts.hasQuery,
      fragment: fragmentParts.fragment,
      host: "",
      password: undefined,
      path,
      port: undefined,
      query: queryParts.query,
      scheme: "",
      username: undefined,
    };
  }

  return {
    ...authorityParts,
    hasAuthority,
    hasFragment: fragmentParts.hasFragment,
    hasQuery: queryParts.hasQuery,
    fragment: fragmentParts.fragment,
    path,
    query: queryParts.query,
    scheme,
  };
}
